export interface App_icons {
  /**
   * Create a new icon from triangle geometry.
   * @returns Unique icon value (pass to interface ``icon_value`` argument).
   * @param range Pair of ints.
   * @param coords Sequence of bytes (6 floats for one triangle) for (X, Y) coordinates.
   * @param colors Sequence of bytes (12 for one triangle) for RGBA.
   */
  new_triangles(range: H.In<readonly [number, number]>, coords: H.In<H.Bytes>, colors: H.In<H.Bytes>): H.Ref<number>;
  /**
   * Create a new icon from triangle geometry.
   * @returns Unique icon value (pass to interface ``icon_value`` argument).
   * @param range Pair of ints.
   * @param coords Sequence of bytes (6 floats for one triangle) for (X, Y) coordinates.
   * @param colors Sequence of bytes (12 for one triangle) for RGBA.
   */
  new_triangles(kw: {
    /** Pair of ints. */
    range: H.In<readonly [number, number]>;
    /** Sequence of bytes (6 floats for one triangle) for (X, Y) coordinates. */
    coords: H.In<H.Bytes>;
    /** Sequence of bytes (12 for one triangle) for RGBA. */
    colors: H.In<H.Bytes>;
  }): H.Ref<number>;
  /**
   * Create a new icon from triangle geometry.
   * @returns Unique icon value (pass to interface ``icon_value`` argument).
   * @param filepath File path.
   */
  new_triangles_from_file(filepath: H.In<string | H.Bytes>): H.Ref<number>;
  /**
   * Create a new icon from triangle geometry.
   * @returns Unique icon value (pass to interface ``icon_value`` argument).
   * @param filepath File path.
   */
  new_triangles_from_file(kw: {
    /** File path. */
    filepath: H.In<string | H.Bytes>;
  }): H.Ref<number>;
  /**
   * Release the icon.
   * @param icon_id The icon id to release.
   */
  release(icon_id: H.In<number>): H.Ref<void>;
  /**
   * Release the icon.
   * @param icon_id The icon id to release.
   */
  release(kw: {
    /** The icon id to release. */
    icon_id: H.In<number>;
  }): H.Ref<void>;
}

export interface App_timers {
  /**
   * Check if this function is registered as a timer.
   * @returns True when this function is registered, otherwise False.
   * @param function_ Function to check.
   */
  is_registered(function_: any): H.Ref<boolean>;
  /**
   * Check if this function is registered as a timer.
   * @returns True when this function is registered, otherwise False.
   * @param function_ Function to check.
   */
  is_registered(kw: {
    /** Function to check. */
    function: any;
  }): H.Ref<boolean>;
  /**
   * Add a new function that will be called after the specified amount of seconds.
   * The function gets no arguments and is expected to return either None or a float.
   * If ``None`` is returned, the timer will be unregistered.
   * A returned number specifies the delay until the function is called again.
   * ``functools.partial`` can be used to assign some parameters.
   * @param function_ The function that should called.
   */
  register(function_: any, kw?: {
    /** Seconds until the callback should be called the first time. */
    first_interval?: H.In<number>;
    /** Don't remove timer when a new file is loaded. */
    persistent?: H.In<boolean>;
  }): H.Ref<void>;
  /**
   * Add a new function that will be called after the specified amount of seconds.
   * The function gets no arguments and is expected to return either None or a float.
   * If ``None`` is returned, the timer will be unregistered.
   * A returned number specifies the delay until the function is called again.
   * ``functools.partial`` can be used to assign some parameters.
   * @param function_ The function that should called.
   */
  register(kw: {
    /** The function that should called. */
    function: any;
    /** Seconds until the callback should be called the first time. */
    first_interval?: H.In<number>;
    /** Don't remove timer when a new file is loaded. */
    persistent?: H.In<boolean>;
  }): H.Ref<void>;
  /**
   * Unregister timer.
   * @param function_ Function to unregister.
   */
  unregister(function_: any): H.Ref<void>;
  /**
   * Unregister timer.
   * @param function_ Function to unregister.
   */
  unregister(kw: {
    /** Function to unregister. */
    function: any;
  }): H.Ref<void>;
}

