/** bpy: Blender 5.2.1 LTS's Python API. */
export interface Bpy {
  /** The open file's data: objects, meshes, materials, scenes, ... */
  readonly data: H.Own<R.BlendData>;
  /** The current context: the scene, the view layer, the active and selected objects, the editor. */
  readonly context: H.Own<Context>;
  /** Every operator, by module: bpy.ops.mesh.primitive_cube_add({ size: 2 }). */
  readonly ops: O.Ops;
  readonly types: Types;
  readonly app: App;
  readonly utils: P.bpy_utils.Api;
  readonly path: P.bpy_path.Api;
  readonly props: P.bpy_props.Api;
  readonly msgbus: P.bpy_msgbus.Api;
}
